const pending = new Set(['PHASE1_QUALIFIED', 'PHASE2_RETRY']);
const seen = new Set();
const output = [];
const now = Date.now();
for (const item of $input.all()) {
  const status = String(item.json.status || '').trim().toUpperCase();
  const productName = String(item.json.product_name || '').trim();
  const query = String(item.json.search_query || '').trim().toLowerCase();
  const opportunityId = String(item.json.opportunity_id || (item.json.source_id ? 'reddit:' + item.json.source_id : 'legacy:' + productName.toLowerCase() + '|' + query));
  const nextRetry = Date.parse(String(item.json.phase2_next_retry_at || ''));
  if (status === 'PHASE2_RETRY' && Number.isFinite(nextRetry) && nextRetry > now) continue;
  let remaining = item.json.phase2_remaining_product_ids || [];
  if (typeof remaining === 'string') { try { remaining = JSON.parse(remaining); } catch { remaining = []; } }
  if (!Array.isArray(remaining)) remaining = [];
  remaining = [...new Set(remaining.map(String).filter(id => /^\d{10,}$/.test(id)))].slice(0, 10);
  const key = `${opportunityId}|${query}`;
  if (!pending.has(status) || !productName || !query || seen.has(key)) continue;
  seen.add(key);
  output.push({ json: { ...item.json, opportunity_id: opportunityId, source_phase1_status: status, search_query: query, resume_product_ids: remaining, phase2_retry_count: Number(item.json.phase2_retry_count || 0) } });
}
return output.slice(0, 10);

return $input.all().map((item, index) => {
  const response = item.json;
  const opportunity = $('Select all pending accepted opportunities').itemMatching(index).json;
  const results = response.search?.results || [];
  const queryTokens = new Set(String(opportunity.search_query || '').toLowerCase().split(/\W+/).filter(token => token.length > 2));
  const ranked = results.map(product => {
    const titleTokens = new Set(String(product.title || '').toLowerCase().split(/\W+/));
    const overlap = [...queryTokens].filter(token => titleTokens.has(token)).length;
    const relevance = queryTokens.size ? overlap / queryTokens.size : 0;
    const rating = Number(product.rating || 0);
    const reviews = Number(product.review_count || 0);
    const orders = Number(product.orders_count || 0);
    const score = relevance * 45 + Math.min(rating / 5, 1) * 15 + Math.min(Math.log10(reviews + 1) / 3, 1) * 10 + Math.min(Math.log10(orders + 1) / 4, 1) * 10 + (product.min_price != null ? 10 : 0) + (product.image ? 5 : 0) + (product.canonical_url || product.url ? 5 : 0);
    return { ...product, deterministic_score: Math.round(score), query_overlap: overlap };
  }).filter(product => product.product_id && product.title && product.query_overlap > 0).sort((a, b) => b.deterministic_score - a.deterministic_score).slice(0, 10);
  return { json: { opportunity, search_run_id: response.search_run_id || null, search_status: response.status || 'error', search_error: response.error || null, search_warnings: response.search?.warnings || [], candidates: ranked, product_ids: ranked.map(product => product.product_id) }, pairedItem:{item:index} };
});

const researchById = new Map($('Rank candidates deterministically').all().map(item => [String(item.json.opportunity?.opportunity_id || ''), item.json]));
return $input.all().flatMap((item, index) => {
  const response = item.json;
  const context = response.context || {};
  const opportunityId = String(context.opportunity_id || '');
  if (!opportunityId) throw new Error('Missing opportunity_id in scrape context');
  const research = researchById.get(opportunityId);
  const scoreById = Object.fromEntries((research?.candidates || []).map(row => [String(row.product_id), row.deterministic_score]));
  const output = [];
  for (const result of response.results || []) {
    const snapshot = result.snapshot;
    const price = snapshot?.eligible_min_price ?? snapshot?.min_price;
    const usable = snapshot?.product_id && snapshot?.title && snapshot?.currency === 'EUR' && snapshot?.destination_country === 'FR' && price != null && Number(snapshot?.eligible_variant_count || 0) > 0;
    if (!usable) continue;
    const cleanTitle = String(snapshot.title).replace(/\s*-\s*AliExpress(?:\s+\d+)?\s*$/i, '').trim();
    const evaluationKey = opportunityId + '|' + snapshot.product_id + '|FR';
    output.push({ json: { opportunity_id: opportunityId, source_id: context.source_id || null, source_url: context.source_url || null, source_product: context.product_name, search_query: context.search_query, product_id: snapshot.product_id, destination_country: 'FR', evaluation_key: evaluationKey, phase2_search_run_id: context.search_run_id || null, title: cleanTitle, price, max_price: snapshot.eligible_max_price ?? snapshot.max_price, currency: snapshot.currency, source: 'AliExpress', link: snapshot.canonical_url || snapshot.requested_url, rating: snapshot.rating, review_count: snapshot.review_count, orders_count: snapshot.orders_count, supplier_name: snapshot.supplier?.name || null, supplier_feedback: snapshot.supplier?.positive_feedback ?? null, eligible_variant_count: snapshot.eligible_variant_count, deterministic_score: scoreById[String(snapshot.product_id)] ?? null, snapshot_status: snapshot.status, warnings: snapshot.warnings || [], status: 'RESEARCHED' }, pairedItem:{item:index} });
  }
  return output;
});

const writtenIds = new Set($('Normalize detailed products').all().map(item => String(item.json.opportunity_id || '')));
return $('Scrape top 10 product details').all().flatMap(item => {
  const scrape = item.json;
  const context = scrape.context || {};
  const opportunityId = String(context.opportunity_id || '');
  if (!opportunityId || !writtenIds.has(opportunityId)) return [];
  const remaining = Array.isArray(scrape.remaining_product_ids) ? [...new Set(scrape.remaining_product_ids.map(String))] : [];
  const retryCount = Number(context.retry_count || 0) + (remaining.length ? 1 : 0);
  const exhausted = retryCount >= 5;
  const delayMinutes = Math.min(1440, 30 * Math.pow(2, Math.max(0, retryCount - 1)));
  return [{json:{opportunity_id:opportunityId,search_query:context.search_query,product_name:context.product_name,status:remaining.length ? (exhausted ? 'PHASE2_FAILED' : 'PHASE2_RETRY') : 'PHASE2_RESEARCHED',phase2_remaining_product_ids:JSON.stringify(remaining),phase2_retry_count:retryCount,phase2_next_retry_at:remaining.length && !exhausted ? new Date(Date.now()+delayMinutes*60000).toISOString() : '',phase2_run_id:scrape.execution_id || context.search_run_id || '',phase2_error:scrape.error || ''}}];
});

const response = $json;
const opportunity = response.context || response.opportunity || {};
const effectiveStatus = String(response.status || response.search_status || 'error').toLowerCase();
const remaining = Array.isArray(response.remaining_product_ids) ? [...new Set(response.remaining_product_ids.map(String))] : [];
const retry = effectiveStatus === 'blocked' || effectiveStatus === 'error' || remaining.length > 0;
const retryCount = Number(opportunity.retry_count ?? opportunity.phase2_retry_count ?? 0) + (retry ? 1 : 0);
const exhausted = retryCount >= 5;
const delayMinutes = Math.min(1440, 30 * Math.pow(2, Math.max(0, retryCount - 1)));
return {json:{opportunity_id:opportunity.opportunity_id,search_query:opportunity.search_query,product_name:opportunity.product_name,status:retry ? (exhausted ? 'PHASE2_FAILED' : 'PHASE2_RETRY') : 'PHASE2_NO_MATCH',phase2_remaining_product_ids:JSON.stringify(remaining),phase2_retry_count:retryCount,phase2_next_retry_at:retry && !exhausted ? new Date(Date.now()+delayMinutes*60000).toISOString() : '',phase2_run_id:response.execution_id || response.search_run_id || opportunity.search_run_id || '',phase2_error:response.error || response.search_error || null}};
